 5	public final class InsertionSort {
 6	
 7	    private InsertionSort() {
 8	        // Utility class.
 9	    }
10	
11	    public static void sort(int[] values) {
12	        requireArray(values);
13	        sort(values, IndexRange.forArray(values.length));
14	    }
15	
16	    public static void sortRange(int[] values, int startInclusive, int endExclusive) {
17	        requireArray(values);
18	        sort(values, IndexRange.of(values.length, startInclusive, endExclusive));
19	    }
20	
21	    public static boolean isSorted(int[] values) {
22	        requireArray(values);
23	        return isSorted(values, IndexRange.forArray(values.length));
24	    }
25	
26	    public static boolean isSortedRange(int[] values, int startInclusive, int endExclusive) {
27	        requireArray(values);
28	        return isSorted(values, IndexRange.of(values.length, startInclusive, endExclusive));
29	    }
30	
31	    public static int[] sortedCopy(int[] values) {
32	        requireArray(values);
33	
34	        int[] copy = Arrays.copyOf(values, values.length);
35	        sort(copy);
36	        return copy;
37	    }
38	
39	    private static void sort(int[] values, IndexRange range) {
40	        if (range.hasFewerThanTwoElements()) {
41	            return;
42	        }
43	
44	        for (int currentIndex = range.startInclusive() + 1;
45	                currentIndex < range.endExclusive();
46	                currentIndex++) {
47	            insertValue(values, range.startInclusive(), currentIndex);
48	        }
49	    }
50	
51	    private static boolean isSorted(int[] values, IndexRange range) {
52	        for (int index = range.startInclusive() + 1; index < range.endExclusive(); index++) {
53	            if (values[index - 1] > values[index]) {
54	                return false;
55	            }
56	        }
57	
58	        return true;
59	    }
60	
61	    private static void insertValue(int[] values, int startInclusive, int currentIndex) {
62	        int valueToInsert = values[currentIndex];
63	        int insertionIndex = findInsertionIndex(values, startInclusive, currentIndex, valueToInsert);
64	
65	        shiftRight(values, insertionIndex, currentIndex);
66	        values[insertionIndex] = valueToInsert;
67	    }
68	
69	    private static int findInsertionIndex(
70	            int[] values,
71	            int startInclusive,
72	            int currentIndex,
73	            int valueToInsert) {
74	        int scanIndex = currentIndex - 1;
75	
76	        while (scanIndex >= startInclusive && values[scanIndex] > valueToInsert) {
77	            scanIndex--;
78	        }
79	
80	        return scanIndex + 1;
81	    }
82	
83	    private static void shiftRight(int[] values, int startIndex, int endIndex) {
84	        int length = endIndex - startIndex;
85	        if (length > 0) {
86	            System.arraycopy(values, startIndex, values, startIndex + 1, length);
87	        }
88	    }
89	
90	    private static void requireArray(int[] values) {
91	        if (values == null) {
92	            throw new IllegalArgumentException("values must not be null");
93	        }
94	    }
95	}

